require_once __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/schema.php';$schema=dental_schema($pdo);$labId=$schema->labId();$serviceId=$schema->serviceId();$serviceName=$schema->serviceName();$imageId=$schema->imageId();$imagePath=$schema->imagePath();$published=$schema->status('valide');
$q=$pdo->prepare('SELECT COUNT(*) AS labs,COUNT(DISTINCT ville) AS cities FROM laboratoire WHERE statut=?');$q->execute([$published]);$stats=$q->fetch();$serviceCount=(int)$pdo->query('SELECT COUNT(*) FROM service')->fetchColumn();
$sql="SELECT s.`$serviceId` id,s.`$serviceName` nom FROM service s WHERE s.`$serviceName` IN ('Couronne','Bridge','Facette','Prothèse complète','Prothèse sur implant','Appareils orthodontiques') ORDER BY FIELD(s.`$serviceName`,'Couronne','Bridge','Facette','Prothèse complète','Prothèse sur implant','Appareils orthodontiques')";$services=$pdo->query($sql)->fetchAll();
$sql="SELECT l.`$labId` id,l.nom_laboratoire,l.ville,l.description,(SELECT i.`$imagePath` FROM image_laboratoire i WHERE i.laboratoire_id=l.`$labId` ORDER BY i.`$imageId` LIMIT 1) photo,GROUP_CONCAT(DISTINCT s.`$serviceName` ORDER BY s.`$serviceName` SEPARATOR '|') services FROM laboratoire l LEFT JOIN laboratoire_service ls ON ls.laboratoire_id=l.`$labId` LEFT JOIN service s ON s.`$serviceId`=ls.service_id WHERE l.statut=? GROUP BY l.`$labId` ORDER BY l.`$labId` DESC LIMIT 3";$q=$pdo->prepare($sql);$q->execute([$published]);$labs=$q->fetchAll();
